#!/usr/bin/env bash
# colors.sh - Bash color and logging helpers (Linux best practices)
# Use: source this file in your scripts to get consistent logging functions

# Prevent multiple sourcing
[[ -n "${_COLORS_SH_INCLUDED:-}" ]] && return
_COLORS_SH_INCLUDED=1

# -----------------------------
# ANSI color codes
# -----------------------------
RED="\033[0;31m"
YELLOW="\033[0;33m"
GREEN="\033[0;32m"
CYAN="\033[0;36m"
NC="\033[0m"  # No Color / reset

# -----------------------------
# Logging / output functions
# -----------------------------
echo_success() {
  echo -e "${GREEN}✔ $*${NC}"
}

echo_error() {
    echo -e "${RED}✖ $*${NC}"
}

echo_warn() {
    echo -e "${YELLOW}⚠ $*${NC}"
}

echo_section() {
    echo -e "\n${CYAN}=== $* ===${NC}"
}

echo_info() {
    echo -e "$*"
}

prompt() {
    local message="$1"
    local var="$2"
    read -rp "→ $message" "$var"
}

services:
  ##################################################################################
  ## Application backend ###########################################################
  ##################################################################################

  backend:
    container_name: truspace-backend
    # build or pull image determined by env variable BUILD_OR_PULL_IMAGES or --dev flag in start.sh
    restart: on-failure
    environment:
      NODE_ENV: ${NODE_ENV}
      PORT: ${API_PORT}
      IPFS_CLUSTER_HOST: ${IPFS_CLUSTER_HOST}
      IPFS_GATEWAY_HOST: ${IPFS_GATEWAY_HOST}
      IPFS_PINSVC_HOST: ${IPFS_PINSVC_HOST}
      OLLAMA_MODEL: ${OLLAMA_MODEL}
      OPENWEBUI_HOST: ${OPENWEBUI_HOST}
      WEBUI_SECRET_KEY: ${WEBUI_SECRET_KEY}
      ADMIN_USER_EMAIL: ${ADMIN_USER_EMAIL}
      ADMIN_USER_PASSWORD: ${ADMIN_USER_PASSWORD}
      AUTO_DOWNLOAD: ${AUTO_DOWNLOAD}
      DISABLE_ALL_AI_FUNCTIONALITY: ${DISABLE_ALL_AI_FUNCTIONALITY}
      MALWARE_SCANNING_ENABLED: ${MALWARE_SCANNING_ENABLED}
      CLAMAV_HOST: ${CLAMAV_HOST}
      CLAMAV_PORT: ${CLAMAV_PORT}
      CLAMAV_TIMEOUT_MS: ${CLAMAV_TIMEOUT_MS}
      DATABASE_PATH: /app/data/truspace.db
      JWT_SECRET: ${JWT_SECRET}
      JWT_MAX_AGE: ${JWT_MAX_AGE}
      CORS_ORIGIN: ${CORS_ORIGIN}
      REGISTER_USERS_AS_INACTIVE: ${REGISTER_USERS_AS_INACTIVE}
      LOG_LEVEL: ${LOG_LEVEL}
      RESTRICTED_EMAIL_DOMAINS: ${RESTRICTED_EMAIL_DOMAINS}
      SMTP_HOST: ${SMTP_HOST}
      SMTP_USER: ${SMTP_USER}
      SMTP_PASSWORD: ${SMTP_PASSWORD}
      SMTP_PORT: ${SMTP_PORT}
      SMTP_SSL: ${SMTP_SSL}
      SMTP_TLS: ${SMTP_TLS}
      EMAIL_SENDER: ${EMAIL_SENDER}
      RUN_SEEDS: ${RUN_SEEDS:-false}
    ports:
      - ${API_PORT}:${API_PORT}
    entrypoint: sh ./entrypoint.sh
    volumes:
      - ./volumes/db:/app/data
      - ./volumes/clamav-scan:/scan
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"

  ##################################################################################
  ## IPFS & Cluster PEER 0 #########################################################
  ##################################################################################

  ipfs0:
    container_name: ipfs0
    image: ipfs/kubo:${VERSION_IPFS:-master-latest}
    restart: unless-stopped
    user: ${LUID}:${LGID}
    ports:
      - "${SWARM_PORT}:${SWARM_PORT}" # ipfs swarm - expose if needed/wanted
      - "${IPFS_API_PORT}:${IPFS_API_PORT}" # ipfs api - expose if needed/wanted
      - "${IPFS_GATEWAY_PORT}:${IPFS_GATEWAY_PORT}" # ipfs gateway - expose if needed/wanted
    volumes:
        - ./volumes/ipfs0:/data/ipfs
        - ./scripts/init-ipfs-config.sh:/init-ipfs-config.sh:ro
    entrypoint: ["/init-ipfs-config.sh", "${SWARM_PORT}", "${IPFS_API_PORT}", "${IPFS_GATEWAY_PORT}"] # Custom entrypoint to setup network settings with no bootstrapping
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"

  cluster0:
    container_name: cluster0
    image: ipfs/ipfs-cluster:${VERSION_IPFS_CLUSTER:-master-latest}
    restart: unless-stopped
    user: ${LUID}:${LGID}
    depends_on:
      - ipfs0
    environment:
      CLUSTER_PEERNAME: ${CLUSTER_PEERNAME_0}
      CLUSTER_IPFSHTTP_NODEMULTIADDRESS: ${CLUSTER_IPFSHTTP_NODEMULTIADDRESS_0}
      CLUSTER_CRDT_TRUSTEDPEERS: ${CLUSTER_CRDT_TRUSTEDPEERS_0} # Trust all peers in Cluster
      CLUSTER_RESTAPI_HTTPLISTENMULTIADDRESS: ${CLUSTER_RESTAPI_HTTPLISTENMULTIADDRESS} # Expose API
      CLUSTER_PINSVCAPI_HTTPLISTENMULTIADDRESS: ${CLUSTER_PINSVCAPI_HTTPLISTENMULTIADDRESS} # Exposes Pinning Service API
      CLUSTER_MONITORPINGINTERVAL: ${CLUSTER_MONITORPINGINTERVAL} # Speed up peer discovery
    ports:
      # Open API port (allows ipfs-cluster-ctl usage on host)
      - "${OPEN_API_PORT}:${OPEN_API_PORT}"
      # IPFS pinning service api
      - "${PINNING_SERVICE_PORT}:${PINNING_SERVICE_PORT}"
      # Cluster swarm endpoint
      - "${CLUSTER_SWARM_PORT}:${CLUSTER_SWARM_PORT}"
    volumes:
      - ./volumes/cluster0:/data/ipfs-cluster
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"
